}
.btn-outline-light:hover { background: rgba(255,255,255,.12); border-color: #fff; }

.hero-cta { display: flex; gap: 14px; flex-wrap: wrap; }

.hero-scroll-indicator {
  position: absolute;
  bottom: 28px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
