  50% { transform: translateY(6px); opacity: .4; }
}

/* ===== Section headers ===== */
.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 32px;
  gap: 16px;
}

.section-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 6px;
}

.section-title {
  font-family: var(--font-serif);
  font-size: clamp(24px, 3vw, 34px);
  font-weight: 400;
  line-height: 1.2;
}

.view-all-link {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text);
  display: flex;
  align-items: center;
  gap: 4px;
  border-bottom: 1px solid var(--color-text);
  padding-bottom: 1px;
  white-space: nowrap;
  transition: color var(--transition), border-color var(--transition);
  flex-shrink: 0;
}
.view-all-link:hover { color: var(--color-accent); border-color: var(--color-accent); }
.view-all-link:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

/* ===== Category Strip ===== */
.categories {
  padding: 48px 0 0;
}

.category-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 14px;
}

.category-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  text-align: center;
  padding: 24px 12px;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  transition: box-shadow var(--transition), border-color var(--transition), transform var(--transition);
  text-decoration: none;
  color: var(--color-text);
}
.category-card:hover {
  box-shadow: var(--shadow-md);
  border-color: transparent;
  transform: translateY(-2px);
}
.category-card:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.category-icon {
  width: 52px; height: 52px;
  background: var(--color-bg);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 26px;
}

.category-name {
  font-size: 13px;
  font-weight: 600;
}

.category-count {
  font-size: 11px;
  color: var(--color-text-muted);
}

/* ===== Featured Products ===== */
.featured-products {
  padding: 72px 0;
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.product-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: box-shadow var(--transition), transform var(--transition);
  display: flex;
  flex-direction: column;
}
.product-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}

.product-image-wrap {
  position: relative;
  aspect-ratio: 4/3;
  overflow: hidden;
  background: var(--color-bg);
}

.product-image-wrap img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .4s ease;
}
.product-card:hover .product-image-wrap img { transform: scale(1.04); }

.product-badges {
  position: absolute;
  top: 12px; left: 12px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.badge {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: 3px 8px;
  border-radius: 3px;
  line-height: 1.5;
}
.badge-new { background: var(--color-badge); color: #fff; }
.badge-sale { background: var(--color-deal); color: #fff; }
.badge-bestseller { background: #2e7d32; color: #fff; }

.product-wishlist {
  position: absolute;
  top: 12px; right: 12px;
  background: rgba(255,255,255,.85);
  border: none;
  border-radius: 50%;
  width: 34px; height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-muted);
  transition: color var(--transition), background var(--transition);
  backdrop-filter: blur(4px);
}
.product-wishlist:hover,
.product-wishlist[aria-pressed="true"] { color: var(--color-accent); background: #fff; }
.product-wishlist:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.product-body {
  padding: 16px 16px 20px;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.product-category {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--color-text-muted);
  margin-bottom: 5px;
}

.product-name {
  font-size: 15px;
  font-weight: 600;
  line-height: 1.35;
  margin-bottom: 6px;
}

.product-rating {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 12px;
}

.stars {
  display: flex;
  gap: 1px;
  color: #f59e0b;
}
.stars svg { width: 12px; height: 12px; }

.rating-count {
  font-size: 12px;
  color: var(--color-text-muted);
}

.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: auto;
}

.product-price {
  display: flex;
  align-items: baseline;
  gap: 7px;
}

.price-current {
  font-size: 17px;
  font-weight: 700;
}

.price-original {
  font-size: 13px;
  color: var(--color-text-muted);
  text-decoration: line-through;
}

.add-to-cart {
  background: var(--color-badge);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  padding: 9px 14px;
  font-size: 12px;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 5px;
  transition: background var(--transition), transform var(--transition);
  white-space: nowrap;
}
.add-to-cart:hover { background: #333; }
.add-to-cart:active { transform: scale(.97); }
.add-to-cart:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}
.add-to-cart.added { background: #2e7d32; }

/* ===== Deals Section ===== */
.deals-section {
  padding: 0 0 72px;
}

.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.deal-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  min-height: 260px;
  display: flex;
  align-items: flex-end;
  text-decoration: none;
  color: #fff;
}
.deal-card:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 3px;
}

.deal-card img {
  position: absolute;
  inset: 0;
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .5s ease;
}
.deal-card:hover img { transform: scale(1.04); }

.deal-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,.72) 0%, rgba(0,0,0,.15) 60%, transparent 100%);
}

.deal-content {
  position: relative;
  z-index: 1;
  padding: 28px;
}

.deal-tag {
  display: inline-block;
  background: var(--color-accent);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 3px;
  margin-bottom: 10px;
}

.deal-title {
  font-family: var(--font-serif);
  font-size: 22px;
  font-weight: 400;
  line-height: 1.2;
  margin-bottom: 6px;
}

.deal-subtitle {
  font-size: 13px;
  opacity: .8;
  margin-bottom: 16px;
}

.deal-cta {
  font-size: 13px;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border-bottom: 1px solid rgba(255,255,255,.5);
  padding-bottom: 2px;
  transition: border-color var(--transition);
}
.deal-card:hover .deal-cta { border-color: #fff; }

.deal-card.deal-card--wide {
  grid-column: 1 / -1;
  min-height: 200px;
}

.deal-card--wide .deal-content {
  max-width: 480px;
}

/* ===== Countdown Timer ===== */
.countdown-section {
  background: var(--color-badge);
  color: #fff;
  padding: 40px 0;
  text-align: center;
  margin-bottom: 72px;
}

.countdown-inner {
  max-width: 600px;
  margin: 0 auto;
}

.countdown-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 8px;
}

.countdown-title {
  font-family: var(--font-serif);
  font-size: 28px;
  font-weight: 400;
  margin-bottom: 24px;
}

.countdown-timer {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.timer-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.timer-number {
  background: rgba(255,255,255,.1);
  border: 1px solid rgba(255,255,255,.15);
  border-radius: 8px;
  width: 72px; height: 72px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 30px;
  font-weight: 700;
  letter-spacing: -.02em;
  font-variant-numeric: tabular-nums;
}

.timer-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: rgba(255,255,255,.55);
}

.timer-colon {
  font-size: 28px;
  font-weight: 300;
  margin-bottom: 14px;
  color: rgba(255,255,255,.4);
}

/* ===== Editorial / Stories ===== */
.editorial {
  padding: 0 0 80px;
}

.editorial-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr;
  gap: 20px;
}

.editorial-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition), transform var(--transition);
  text-decoration: none;
  color: var(--color-text);
}
.editorial-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}
.editorial-card:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 3px;
}

.editorial-image-wrap {
  position: relative;
  overflow: hidden;
}
.editorial-card:first-child .editorial-image-wrap { aspect-ratio: 16/9; }
.editorial-card:not(:first-child) .editorial-image-wrap { aspect-ratio: 4/3; }

.editorial-image-wrap img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .45s ease;
}
.editorial-card:hover .editorial-image-wrap img { transform: scale(1.05); }

.editorial-tag {
  position: absolute;
  top: 14px; left: 14px;
  background: rgba(0,0,0,.7);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 3px;
  backdrop-filter: blur(4px);
}

.editorial-body {
  padding: 20px;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.editorial-title {
  font-family: var(--font-serif);
  font-size: 18px;
  font-weight: 400;
  line-height: 1.3;
  margin-bottom: 8px;
}
.editorial-card:first-child .editorial-title { font-size: 22px; }

.editorial-excerpt {
  font-size: 13px;
  color: var(--color-text-muted);
  line-height: 1.6;
  margin-bottom: 16px;
  flex: 1;
}

.editorial-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 12px;
  color: var(--color-text-muted);
  padding-top: 14px;
  border-top: 1px solid var(--color-border);
}

.editorial-author {
  display: flex;
  align-items: center;
  gap: 7px;
}
.editorial-author img {
  width: 26px; height: 26px;
  border-radius: 50%;
  object-fit: cover;
}

.editorial-dot { width: 3px; height: 3px; background: currentColor; border-radius: 50%; }

/* ===== Trust Badges ===== */
.trust-strip {
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
  padding: 36px 0;
  margin-bottom: 72px;
}

.trust-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.trust-item {
  display: flex;
  align-items: center;
  gap: 14px;
}

.trust-icon {
  width: 44px; height: 44px;
  background: var(--color-bg);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--color-accent);
}

.trust-text strong {
  display: block;
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 2px;
}
.trust-text span { font-size: 12px; color: var(--color-text-muted); }

/* ===== Newsletter ===== */
.newsletter {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 56px 48px;
  margin-bottom: 72px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.newsletter-heading {
  font-family: var(--font-serif);
  font-size: clamp(26px, 3vw, 38px);
  font-weight: 400;
  line-height: 1.2;
  margin-bottom: 12px;
}

.newsletter-desc {
  font-size: 14px;
  color: var(--color-text-muted);
  line-height: 1.65;
}

.newsletter-form {
  display: flex;
  gap: 10px;
}

.newsletter-form input[type="email"] {
  flex: 1;
  padding: 13px 16px;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius);
  font-size: 14px;
  background: var(--color-bg);
  color: var(--color-text);
  transition: border-color var(--transition), box-shadow var(--transition);
  outline: none;
}
.newsletter-form input[type="email"]::placeholder { color: var(--color-text-muted); }
.newsletter-form input[type="email"]:focus {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(212,83,26,.1);
}

.newsletter-note {
  font-size: 11px;
  color: var(--color-text-muted);
  margin-top: 10px;
}

/* ===== Footer ===== */
.site-footer {
  background: var(--color-badge);
  color: rgba(255,255,255,.75);
  padding: 60px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
}

.footer-brand .nav-logo {
  color: #fff;
  font-size: 22px;
  display: inline-block;
  margin-bottom: 14px;
}

.footer-brand p {
  font-size: 13px;
  line-height: 1.7;
  max-width: 260px;
}

.footer-social {
  display: flex;
  gap: 10px;
  margin-top: 20px;
}

.social-btn {
  width: 36px; height: 36px;
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,.7);
  transition: background var(--transition), color var(--transition);
}
.social-btn:hover { background: rgba(255,255,255,.16); color: #fff; }
.social-btn:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.footer-col h3 {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: #fff;
  margin-bottom: 16px;
}

.footer-links {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-links a {
  font-size: 13px;
  color: rgba(255,255,255,.6);
  transition: color var(--transition);
}
.footer-links a:hover { color: #fff; }
.footer-links a:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,.1);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  font-size: 12px;
}

.footer-legal { display: flex; gap: 20px; }
.footer-legal a { color: rgba(255,255,255,.5); transition: color var(--transition); }
.footer-legal a:hover { color: #fff; }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: repeat(2, 1fr); }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-card:first-child { grid-column: 1 / -1; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .category-grid { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-search { display: none; }
  .menu-btn { display: flex; }

  .deals-grid { grid-template-columns: 1fr; }
  .deal-card.deal-card--wide { grid-column: 1; }

  .trust-grid { grid-template-columns: 1fr 1fr; }

  .newsletter {
    grid-template-columns: 1fr;
    padding: 36px 24px;
    gap: 28px;
  }
  .newsletter-form { flex-direction: column; }

  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card:first-child { grid-column: 1; }

  .footer-grid { grid-template-columns: 1fr 1fr; }
  .footer-bottom { flex-direction: column; text-align: center; }
}

@media (max-width: 540px) {
  .category-grid { grid-template-columns: repeat(2, 1fr); }
  .product-grid { grid-template-columns: 1fr; }
  .trust-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .hero-cta { flex-direction: column; }
  .hero-title { font-size: 34px; }
}

/* ===== Focus visible (extra polish) ===== */
:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
:focus:not(:focus-visible) { outline: none; }
