*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg: #f9f9f7;
  --color-surface: #ffffff;
  --color-border: #e8e8e3;
  --color-text: #1a1a1a;
  --color-text-muted: #6b6b6b;
  --color-accent: #d4531a;
  --color-accent-hover: #b8441400;
  --color-badge: #1a1a1a;
  --color-deal: #d4531a;
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-serif: 'Georgia', 'Times New Roman', serif;
  --radius: 4px;
  --radius-lg: 10px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,.07);
  --shadow-md: 0 4px 16px rgba(0,0,0,.10);
  --transition: 0.22s ease;
  --max-width: 1280px;
  --nav-h: 64px;
}

html { scroll-behavior: smooth; }
body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  font-size: 15px;
}

a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }
button, [role="button"] { cursor: pointer; }
ul { list-style: none; }

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* ===== Skip Link ===== */
.skip-link {
  position: absolute;
  top: -100%;
  left: 0;
  background: var(--color-accent);
  color: #fff;
  padding: 10px 20px;
  font-weight: 600;
  z-index: 9999;
}
.skip-link:focus { top: 0; }

/* ===== Announcement Bar ===== */
.announcement-bar {
  background: var(--color-badge);
  color: #fff;
  text-align: center;
  padding: 9px 24px;
  font-size: 13px;
  letter-spacing: .03em;
}
.announcement-bar a { text-decoration: underline; color: #fff; }

/* ===== Navigation ===== */
.site-nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  height: var(--nav-h);
  display: flex;
  align-items: center;
}

.nav-inner {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-logo {
  font-size: 20px;
  font-weight: 700;
  letter-spacing: -.02em;
  flex-shrink: 0;
}
.nav-logo span { color: var(--color-accent); }

.nav-links {
  display: flex;
  gap: 28px;
  font-size: 14px;
  font-weight: 500;
}
.nav-links a {
  color: var(--color-text-muted);
  transition: color var(--transition);
  padding: 4px 0;
  border-bottom: 2px solid transparent;
}
.nav-links a:hover,
.nav-links a[aria-current="page"] {
  color: var(--color-text);
  border-bottom-color: var(--color-accent);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-left: auto;
}

.nav-search {
  display: flex;
  align-items: center;
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: 20px;
  padding: 6px 14px;
  gap: 8px;
  transition: border-color var(--transition), box-shadow var(--transition);
}
.nav-search:focus-within {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(212,83,26,.12);
}
.nav-search input {
  border: none;
  background: transparent;
  font-size: 13px;
  outline: none;
  width: 160px;
  color: var(--color-text);
}
.nav-search input::placeholder { color: var(--color-text-muted); }
.nav-search svg { color: var(--color-text-muted); flex-shrink: 0; }

.icon-btn {
  background: none;
  border: none;
  padding: 6px;
  border-radius: var(--radius);
  color: var(--color-text);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition);
  position: relative;
}
.icon-btn:hover { background: var(--color-bg); }
.icon-btn:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.cart-badge {
  position: absolute;
  top: 0; right: 0;
  background: var(--color-accent);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  width: 16px; height: 16px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.menu-btn { display: none; }

/* ===== Hero ===== */
.hero {
  background: #1a1a1a;
  color: #fff;
  min-height: 520px;
  display: flex;
  align-items: center;
  position: relative;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  object-fit: cover;
  width: 100%; height: 100%;
  opacity: .45;
}

.hero-inner {
  position: relative;
  z-index: 1;
  max-width: 580px;
}

.hero-eyebrow {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 16px;
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(40px, 5vw, 64px);
  font-weight: 400;
  line-height: 1.1;
  margin-bottom: 20px;
}

.hero-desc {
  font-size: 17px;
  line-height: 1.65;
  color: rgba(255,255,255,.78);
  margin-bottom: 32px;
  max-width: 440px;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 600;
  padding: 13px 28px;
  border-radius: var(--radius);
  border: 2px solid transparent;
  transition: background var(--transition), color var(--transition), border-color var(--transition), box-shadow var(--transition);
  letter-spacing: .01em;
}
.btn:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 3px;
}
.btn-primary {
  background: var(--color-accent);
  color: #fff;
  border-color: var(--color-accent);
}
.btn-primary:hover { background: #b84414; border-color: #b84414; }

.btn-outline-light {
  background: transparent;
  color: #fff;
  border-color: rgba(255,255,255,.55);
}
.btn-outline-light:hover { background: rgba(255,255,255,.12); border-color: #fff; }

.hero-cta { display: flex; gap: 14px; flex-wrap: wrap; }

.hero-scroll-indicator {
  position: absolute;
  bottom: 28px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  color: rgba(255,255,255,.5);
  font-size: 11px;
  letter-spacing: .08em;
  text-transform: uppercase;
}
.scroll-dot {
  width: 4px; height: 4px;
  background: currentColor;
  border-radius: 50%;
  animation: scrollBounce 1.5s ease-in-out infinite;
}
@keyframes scrollBounce {
  0%, 100% { transform: translateY(0); opacity: 1; }
  50% { transform: translateY(6px); opacity: .4; }
}

/* ===== Section headers ===== */
.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 32px;
  gap: 16px;
}

.section-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 6px;
}

.section-title {
  font-family: var(--font-serif);
  font-size: clamp(24px, 3vw, 34px);
  font-weight: 400;
  line-height: 1.2;
}

.view-all-link {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text);
  display: flex;
  align-items: center;
  gap: 4px;
  border-bottom: 1px solid var(--color-text);
  padding-bottom: 1px;
  white-space: nowrap;
  transition: color var(--transition), border-color var(--transition);
  flex-shrink: 0;
}
.view-all-link:hover { color: var(--color-accent); border-color: var(--color-accent); }
.view-all-link:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

/* ===== Category Strip ===== */
.categories {
  padding: 48px 0 0;
}

.category-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 14px;
}

.category-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  text-align: center;
  padding: 24px 12px;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  transition: box-shadow var(--transition), border-color var(--transition), transform var(--transition);
  text-decoration: none;
  color: var(--color-text);
}
.category-card:hover {
  box-shadow: var(--shadow-md);
  border-color: transparent;
  transform: translateY(-2px);
}
.category-card:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.category-icon {
  width: 52px; height: 52px;
  background: var(--color-bg);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 26px;
}

.category-name {
  font-size: 13px;
  font-weight: 600;
}

.category-count {
  font-size: 11px;
  color: var(--color-text-muted);
}

/* ===== Featured Products ===== */
.featured-products {
  padding: 72px 0;
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.product-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: box-shadow var(--transition), transform var(--transition);
  display: flex;
  flex-direction: column;
}
.product-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}

.product-image-wrap {
  position: relative;
  aspect-ratio: 4/3;
  overflow: hidden;
  background: var(--color-bg);
}

.product-image-wrap img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .4s ease;
}
.product-card:hover .product-image-wrap img { transform: scale(1.04); }

.product-badges {
  position: absolute;
  top: 12px; left: 12px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.badge {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: 3px 8px;
  border-radius: 3px;
  line-height: 1.5;
}
.badge-new { background: var(--color-badge); color: #fff; }
.badge-sale { background: var(--color-deal); color: #fff; }
.badge-bestseller { background: #2e7d32; color: #fff; }

.product-wishlist {
  position: absolute;
  top: 12px; right: 12px;
  background: rgba(255,255,255,.85);
  border: none;
  border-radius: 50%;
  width: 34px; height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-muted);
  transition: color var(--transition), background var(--transition);
  backdrop-filter: blur(4px);
}
.product-wishlist:hover,
.product-wishlist[aria-pressed="true"] { color: var(--color-accent); background: #fff; }
.product-wishlist:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.product-body {
  padding: 16px 16px 20px;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.product-category {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--color-text-muted);
  margin-bottom: 5px;
}

.product-name {
  font-size: 15px;
  font-weight: 600;
  line-height: 1.35;
  margin-bottom: 6px;
}

.product-rating {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 12px;
}

.stars {
  display: flex;
  gap: 1px;
  color: #f59e0b;
}
.stars svg { width: 12px; height: 12px; }

.rating-count {
  font-size: 12px;
  color: var(--color-text-muted);
}

.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: auto;
}

.product-price {
  display: flex;
  align-items: baseline;
  gap: 7px;
}

.price-current {
  font-size: 17px;
  font-weight: 700;
}

.price-original {
  font-size: 13px;
  color: var(--color-text-muted);
  text-decoration: line-through;
}

.add-to-cart {
  background: var(--color-badge);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  padding: 9px 14px;
  font-size: 12px;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 5px;
  transition: background var(--transition), transform var(--transition);
  white-space: nowrap;
}
.add-to-cart:hover { background: #333; }
.add-to-cart:active { transform: scale(.97); }
.add-to-cart:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}
.add-to-cart.added { background: #2e7d32; }

/* ===== Deals Section ===== */
.deals-section {
  padding: 0 0 72px;
}

.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.deal-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  min-height: 260px;
  display: flex;
  align-items: flex-end;
  text-decoration: none;
  color: #fff;
}
.deal-card:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 3px;
}

.deal-card img {
  position: absolute;
  inset: 0;
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform .5s ease;
}
.deal-card:hover img { transform: scale(1.04); }

.deal-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,.72) 0%, rgba(0,0,0,.15) 60%, transparent 100%);
}

.deal-content {
  position: relative;
  z-index: 1;
  padding: 28px;
}

.deal-tag {
  display: inline-block;
  background: var(--color-accent);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 3px;
  margin-bottom: 10px;
}

.deal-title {
  font-family: var(--font-serif);
  font-size: 22px;
  font-weight: 400;
  line-height: 1.2;
  margin-bottom: 6px;
}

.deal-subtitle {
  font-size: 13px;
  opacity: .8;
  margin-bottom: 16px;
}

.deal-cta {
  font-size: 13px;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border-bottom: 1px solid rgba(255,255,255,.5);
  padding-bottom: 2px;
  transition: border-color var(--transition);
}
.deal-card:hover .deal-cta { border-color: #fff; }

.deal-card.deal-card--wide {
  grid-column: 1 / -1;
  min-height: 200px;
}

.deal-card--wide .deal-content {
  max-width: 480px;
}

/* ===== Countdown Timer ===== */
.countdown-section {
  background: var(--color-badge);
  color: #fff;
  padding: 40px 0;
  text-align: center;
  margin-bottom: 72px;
}

.countdown-inner {
  max-width: 600px;
  margin: 0 auto;
}

.countdown-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 8px;
}

.countdown-title {
  font-family: var(--font-serif);
  font-size: 28px;
  font-weight: 400;
  margin-bottom: 24px;
}

.countdown-timer {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.timer-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.timer-number {
  background: rgba(255,255,255,.1);
  border: 1px solid rgba(255,255,255,.15);
  border-radius: 8px;
  width: 72px; height: 72px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 30px;
  font-weight: 700;
  letter-spacing: -.02em;
  font-variant-numeric: tabular-nums;
}

.timer-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: rgba(255,255,255,.55);
}

.timer-colon {
  font-size: 28px;
  font-weight: 300;
  margin-bottom: 14px;
  color: rgba(255,255,255,.4);
}

/* ===== Editorial / Stories ===== */
.editorial {
  padding: 0 0 80px;
}

.editorial-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr;
  gap: 20px;
}

.editorial-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition), transform var(--transition);
  text-decoration: none;
  color: var(--color-text);
}
.editorial-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}
.editorial-card:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 3px;
}

.editorial-image-wrap {
  position: relative;
  overflow: hidden;
}
.editorial-card:first-child .editorial-image-wrap { aspect-ratio: 16/9; }
.editorial-card:not(:first-child) .editorial-image-wrap { aspect-ratio: 4/3; }

.editorial-image-wrap img {
  width: 100%; height: 100%;
  object-fit: cover;
