+      this.setAttribute('aria-label', this.getAttribute('aria-label').replace('Add', 'Remove'));
+    } else {
+      icon.setAttribute('fill', 'none');
+      this.setAttribute('aria-label', this.getAttribute('aria-label').replace('Remove', 'Add'));
+    }
+  });
+});
+
+// ===== Countdown Timer =====
+function getTargetDate() {
+  const stored = localStorage.getItem('deal-end-time');
+  if (stored) return new Date(parseInt(stored, 10));
+  const end = new Date(Date.now() + 8 * 60 * 60 * 1000 + 42 * 60 * 1000 + 17 * 1000);
+  localStorage.setItem('deal-end-time', end.getTime().toString());
+  return end;
+}
+
+const targetDate = getTargetDate();
+
+function pad(n) { return String(n).padStart(2, '0'); }
+
+function updateTimer() {
+  const now = Date.now();
+  const diff = Math.max(0, targetDate.getTime() - now);
+
+  const hours = Math.floor(diff / 3_600_000);
+  const minutes = Math.floor((diff % 3_600_000) / 60_000);
+  const seconds = Math.floor((diff % 60_000) / 1_000);
+
+  const els = {
+    hours: document.getElementById('timer-hours'),
+    minutes: document.getElementById('timer-minutes'),
+    seconds: document.getElementById('timer-seconds'),
+  };
+
+  if (els.hours) els.hours.textContent = pad(hours);
+  if (els.minutes) els.minutes.textContent = pad(minutes);
+  if (els.seconds) els.seconds.textContent = pad(seconds);
+
+  const liveRegion = document.getElementById('timer-live');
+  if (liveRegion) {
+    liveRegion.textContent = `${pad(hours)} hours, ${pad(minutes)} minutes, ${pad(seconds)} seconds remaining`;
+  }
+
+  if (diff > 0) requestAnimationFrame(updateTimer);
+}
+
+requestAnimationFrame(updateTimer);
+
+// ===== Mobile Menu =====
+const menuBtn = document.getElementById('menu-btn');
+const mobileNav = document.getElementById('mobile-nav');
+
+if (menuBtn && mobileNav) {
+  menuBtn.addEventListener('click', () => {
+    const expanded = menuBtn.getAttribute('aria-expanded') === 'true';
+    menuBtn.setAttribute('aria-expanded', String(!expanded));
+    mobileNav.hidden = expanded;
+
+    if (!expanded) {
+      const firstLink = mobileNav.querySelector('a');
+      if (firstLink) firstLink.focus();
+    }
+  });
+
+  document.addEventListener('keydown', e => {
+    if (e.key === 'Escape' && !mobileNav.hidden) {
+      mobileNav.hidden = true;
+      menuBtn.setAttribute('aria-expanded', 'false');
+      menuBtn.focus();
+    }
+  });
+}
+
+// ===== Newsletter Form =====
+const newsletterForm = document.getElementById('newsletter-form');
+if (newsletterForm) {
+  newsletterForm.addEventListener('submit', function (e) {
+    e.preventDefault();
+    const input = this.querySelector('input[type="email"]');
+    const msg = document.getElementById('newsletter-msg');
+
+    if (!input.value || !input.validity.valid) {
+      input.focus();
+      return;
+    }
+
+    msg.textContent = 'Thanks for subscribing! Check your inbox for a welcome gift.';
+    msg.style.color = '#2e7d32';
+    input.value = '';
+    this.querySelector('button').disabled = true;
+  });
+}
+
+// ===== Smooth sticky nav shadow =====
+const siteNav = document.querySelector('.site-nav');
+window.addEventListener('scroll', () => {
+  if (window.scrollY > 8) {
+    siteNav.style.boxShadow = '0 2px 12px rgba(0,0,0,.08)';
+  } else {
+    siteNav.style.boxShadow = 'none';
+  }
+}, { passive: true });
+
')

